    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_64(self.amount, serializer);
    sse_encode_u_64(self.fee, serializer);
  }

  @protected
  void sse_encode_i_32(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putInt32(self);
  }

  @protected
  void sse_encode_i_64(PlatformInt64 self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putPlatformInt64(self);
  }

  @protected
  void sse_encode_list_prim_u_8_strict(
    Uint8List self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    serializer.buffer.putUint8List(self);
  }

  @protected
  void sse_encode_list_tx_entry(List<TxEntry> self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    for (final item in self) {
      sse_encode_tx_entry(item, serializer);
    }
  }

  @protected
  void sse_encode_node_tip(NodeTip self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_64(self.height, serializer);
    sse_encode_String(self.nodeVersion, serializer);
  }

  @protected
  void sse_encode_opt_String(String? self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_String(self, serializer);
    }
  }

  @protected
  void sse_encode_opt_box_autoadd_u_64(BigInt? self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_box_autoadd_u_64(self, serializer);
    }
  }

  @protected
  void sse_encode_opt_box_autoadd_u_8(int? self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs

    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_box_autoadd_u_8(self, serializer);
    }
  }

  @protected
  void sse_encode_scan_progress(ScanProgress self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_opt_box_autoadd_u_8(self.percent, serializer);
    sse_encode_String(self.message, serializer);
    sse_encode_bool(self.finished, serializer);
  }

  @protected
  void sse_encode_slate(Slate self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.slateId, serializer);
    sse_encode_String(self.json, serializer);
  }

  @protected
  void sse_encode_tx_entry(TxEntry self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_32(self.id, serializer);
    sse_encode_opt_String(self.slateId, serializer);
    sse_encode_tx_kind(self.kind, serializer);
    sse_encode_i_64(self.createdAtUnix, serializer);
    sse_encode_bool(self.confirmed, serializer);
    sse_encode_u_64(self.amountCredited, serializer);
    sse_encode_u_64(self.amountDebited, serializer);
    sse_encode_opt_box_autoadd_u_64(self.fee, serializer);
    sse_encode_u_32(self.numInputs, serializer);
    sse_encode_u_32(self.numOutputs, serializer);
    sse_encode_opt_String(self.kernelExcess, serializer);
  }

  @protected
  void sse_encode_tx_kind(TxKind self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_u_16(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint16(self);
  }

  @protected
  void sse_encode_u_32(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint32(self);
  }

  @protected
  void sse_encode_u_64(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }

  @protected
  void sse_encode_usize(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_wallet_config(WalletConfig self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.dataDir, serializer);
    sse_encode_chain(self.chain, serializer);
    sse_encode_String(self.nodeUrl, serializer);
    sse_encode_opt_String(self.nodeApiSecret, serializer);
    sse_encode_String(self.epicboxDomain, serializer);
    sse_encode_u_16(self.epicboxPort, serializer);
  }

  @protected
  void sse_encode_wallet_error(WalletError self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_wallet_error_kind(self.kind, serializer);
    sse_encode_String(self.message, serializer);
  }

  @protected
  void sse_encode_wallet_error_kind(
    WalletErrorKind self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_wallet_summary(WalletSummary self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_64(self.lastConfirmedHeight, serializer);
    sse_encode_u_64(self.minimumConfirmations, serializer);
    sse_encode_u_64(self.total, serializer);
    sse_encode_u_64(self.spendable, serializer);
    sse_encode_u_64(self.awaitingConfirmation, serializer);
    sse_encode_u_64(self.awaitingFinalization, serializer);
    sse_encode_u_64(self.immature, serializer);
    sse_encode_u_64(self.locked, serializer);
    sse_encode_bool(self.validatedWithNode, serializer);
  }
}

@sealed
class EpicWalletImpl extends RustOpaque implements EpicWallet {
  // Not to be used by end users
  EpicWalletImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  EpicWalletImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_EpicWallet,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_EpicWallet,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_EpicWalletPtr,
  );

  /// Cancels an unconfirmed transaction by log id and unlocks its outputs.
  Future<void> cancelTransaction({required int txId}) => RustLib.instance.api
      .crateApiWalletEpicWalletCancelTransaction(that: this, txId: txId);

  /// Step 1 of a manual (file/JSON) send: builds the slate and locks the inputs.
  /// Hand `Slate.json` to the recipient; their response goes to `finalize_and_post`.
  Future<Slate> createSendSlate({
    required BigInt amount,
    required BigInt minimumConfirmations,
  }) => RustLib.instance.api.crateApiWalletEpicWalletCreateSendSlate(
    that: this,
    amount: amount,
    minimumConfirmations: minimumConfirmations,
  );

  /// The wallet's epicbox address, `<pubkey>@<epicbox_domain>` (port appended if not 443).
  Future<String> epicboxAddress() =>
      RustLib.instance.api.crateApiWalletEpicWalletEpicboxAddress(that: this);

  /// Fee the wallet would pay to send `amount` now.
  Future<FeeEstimate> estimateFee({
    required BigInt amount,
    required BigInt minimumConfirmations,
  }) => RustLib.instance.api.crateApiWalletEpicWalletEstimateFee(
    that: this,
    amount: amount,
    minimumConfirmations: minimumConfirmations,
  );

  /// Sender side: finalizes the recipient's response and posts the transaction to the node.
  Future<TxEntry> finalizeAndPost({required String slateJson}) =>
      RustLib.instance.api.crateApiWalletEpicWalletFinalizeAndPost(
        that: this,
        slateJson: slateJson,
      );

  /// Recovery phrase of this wallet, re-checked against `password`.
  Future<String> mnemonic({required String password}) => RustLib.instance.api
      .crateApiWalletEpicWalletMnemonic(that: this, password: password);

  /// Recipient side: signs an incoming send slate and returns the response slate JSON.
  Future<Slate> receiveSlate({required String slateJson}) => RustLib
      .instance
      .api
      .crateApiWalletEpicWalletReceiveSlate(that: this, slateJson: slateJson);

  /// Rescans the chain for this wallet's outputs from `start_height` (default: the wallet's
  /// last scanned height, or 1 for a restore), streaming progress until `finished`.
  Stream<ScanProgress> scan({BigInt? startHeight}) => RustLib.instance.api
      .crateApiWalletEpicWalletScan(that: this, startHeight: startHeight);

  /// Balances. With `refresh` the wallet first updates output state from the node.
  Future<WalletSummary> summary({
    required bool refresh,
    required BigInt minimumConfirmations,
  }) => RustLib.instance.api.crateApiWalletEpicWalletSummary(
    that: this,
    refresh: refresh,
    minimumConfirmations: minimumConfirmations,
  );

  /// Transaction log, newest first. With `refresh` it updates from the node first.
  Future<List<TxEntry>> transactions({required bool refresh}) => RustLib
      .instance
      .api
      .crateApiWalletEpicWalletTransactions(that: this, refresh: refresh);
}
